#!/usr/bin/env python3
import sys, os, re, io, gzip, csv, json, datetime as dt
import xml.etree.ElementTree as ET
from decimal import Decimal, getcontext, ROUND_HALF_UP
getcontext().prec = 60

FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
        'oz': Decimal('0.028349523125')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec']

# depot -> (delimiter, columns, base date form, id col, type col, date col, weight col, status col)
DELIM = {
    'east': dict(d=',', cols=['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'], date='YMD',
                 id='id', type='type', ship='shipped', w='gross', st='status', dec='.'),
    'harbor': dict(d='|', cols=['rec', 'ref', 'date', 'weight', 'state'], date='iso',
                   id='ref', type='rec', ship='date', w='weight', st='state', dec='.'),
    'lakeside': dict(d=',', cols=['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
                     date='iso', id='id', type='kind', ship='shipped', w='gross_kg', st='status',
                     dec='.', wunit='kg'),
    'river': dict(d='\t', cols=['t', 'ref', 'shipped', 'weight', 'status'], date='MM/DD/YYYY',
                  id='ref', type='t', ship='shipped', w='weight', st='status', dec='.'),
    'west': dict(d=';', cols=['id', 'typ', 'shipped', 'weight', 'status', 'note'], date='DD.MM.YYYY',
                 id='id', type='typ', ship='shipped', w='weight', st='status', dec=','),
}
HARBOR_ST = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
FW_ST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def norm_status(s):
    return re.sub(r'[ \-]+', '_', (s or '').strip().lower().replace('_', ' ')).replace(' ', '_')


def norm_status2(s):
    return re.sub(r'[\s\-_]+', '_', (s or '').strip().lower())


def counted(s):
    return norm_status2(s) in ('delivered', 'delivered_late')


def norm_type(t):
    t = (t or '').strip().lower()
    if t in ('', 'n', 'new'):
        return 'new'
    if t in ('c', 'cor', 'corr', 'correction', 'amend', 'correct'):
        return 'correction'
    if t in ('v', 'void'):
        return 'void'
    return 'new'


def idnum(s):
    m = re.match(r'^\s*SH\D*?(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def read_bytes(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace')
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16', 'replace')
    enc = 'utf-8'
    head = b[:2000].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([\w\-.]+)', head, re.M | re.I)
    if m:
        enc = m.group(1)
    try:
        return b.decode(enc, 'replace')
    except LookupError:
        return b.decode('utf-8', 'replace')


def parse_date(s, form):
    s = s.strip()
    if 'T' in s or ':' in s:
        return parse_when(s)
    f = (form or 'iso').strip()
    fu = f.upper()
    if fu == 'SERIAL':
        return dt.date(1899, 12, 31) + dt.timedelta(days=int(Decimal(s)))
    if fu in ('ISO', 'YMD', 'YYYY-MM-DD'):
        y, m, d = re.split(r'\D+', s)[:3]
    elif fu in ('DMY', 'DD/MM/YYYY', 'DD.MM.YYYY', 'DD-MM-YYYY'):
