        return dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:7]) - 1)
    elif fu == 'D MON YYYY' or re.search(r'[A-Za-z]', s):
        return parse_when(s)
    else:
        y, m, d = re.split(r'\D+', s)[:3]
    return dt.date(int(y), int(m), int(d))


def parse_when(s):
    s = s.strip()
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})$', s)
    if m:
        return dt.date(int(m.group(3)), MONTHS.index(m.group(2).lower()) + 1, int(m.group(1)))
    d = dt.datetime.fromisoformat(s.replace(' ', 'T') if re.match(r'^\d{4}-\d\d-\d\d \d', s) else s)
    if d.tzinfo is not None:
        d = d.astimezone(dt.timezone.utc)
    return d.date()


def parse_weight(cell, unit, dec):
    m = re.match(r'^\s*([\d.,]+)\s*(kg|g|lb|oz)?\s*$', cell or '', re.I)
    if not m:
        raise ValueError(cell)
    num = m.group(1)
    if dec == ',':
        num = num.replace('.', '').replace(',', '.')
    else:
        num = num.replace(',', '')
    if m.group(2):
        unit = m.group(2).lower()
    return Decimal(num) * FACT[unit]


def unit_of(v):
    m = re.match(r'\s*(kg|g|lb|oz)\b', v or '', re.I)
    return m.group(1).lower() if m else None


